// src/screens/SignupScreen.jsx
// SAME UI as original. Supabase signUp → Django REST /api/auth/register/

import { useState } from "react";
import { registerUser } from "../services/authService";
import { signupBg } from "../assets/images";

export default function SignupScreen({ onNavigate }) {
  const [form, setForm] = useState({
    name: "", contactNumber: "", province: "", municipality: "", barangay: "", password: "",
  });
  const [loading, setLoading] = useState(false);
  const [error, setError]     = useState("");

  const set = (key) => (e) => setForm((f) => ({ ...f, [key]: e.target.value }));

  const handleSignUp = async (e) => {
    e.preventDefault();
    setError("");

    const { name, contactNumber, province, municipality, barangay, password } = form;
    if (!name || !contactNumber || !province || !municipality || !barangay || !password) {
      setError("Please fill in all fields."); return;
    }
    if (password.length < 6) { setError("Password must be at least 6 characters."); return; }
    if (contactNumber.length < 10) { setError("Please enter a valid contact number."); return; }

    setLoading(true);
    // POST /api/auth/register/
    // username = contactNumber (mirrors original email = contactNumber@scarecrow.app logic)
    const { error: regError } = await registerUser(
      contactNumber.trim(),
      password,
      {
        // Extra profile fields — your Django register view should accept these
        full_name:    name.trim(),
        province:     province.trim(),
        municipality: municipality.trim(),
        barangay:     barangay.trim(),
      }
    );

    if (regError) {
      setError(regError);
      setLoading(false);
      return;
    }

    // On success: go to login with phone prefilled (mirrors original behaviour)
    onNavigate("login", { phone: contactNumber.trim() });
    setLoading(false);
  };

  return (
    <div
      className="auth-root"
      style={{ backgroundImage: `url(${signupBg})`, backgroundSize: "cover", backgroundPosition: "center top" }}
    >
      <div className="auth-card" style={{ maxWidth: 480, maxHeight: "90vh", overflowY: "auto" }}>
        <div className="auth-logo">
          <div className="auth-logo-icon">🌾</div>
          <div className="auth-logo-text">Scare<span>Crow</span></div>
        </div>

        <h1 className="auth-title">SIGN UP</h1>
        <p className="auth-subtitle">Please fill in the details</p>

        <form onSubmit={handleSignUp}>
          <div className="form-group">
            <label className="form-label">Name</label>
            <input className="form-input" placeholder="NAME" value={form.name} onChange={set("name")} disabled={loading} />
          </div>

          <div className="form-group">
            <label className="form-label">Contact Number</label>
            <input className="form-input" type="tel" placeholder="CONTACT NUMBER" value={form.contactNumber} onChange={set("contactNumber")} disabled={loading} />
            {form.contactNumber.length > 0 && (
              <p className="form-hint">You'll use {form.contactNumber} to log in</p>
            )}
          </div>

          <div className="form-section-label">Address</div>

          <div className="form-grid">
            <div className="form-group">
              <label className="form-label">Province</label>
              <input className="form-input" placeholder="PROVINCE" value={form.province} onChange={set("province")} disabled={loading} />
            </div>
            <div className="form-group">
              <label className="form-label">Municipality / City</label>
              <input className="form-input" placeholder="MUNICIPALITY / CITY" value={form.municipality} onChange={set("municipality")} disabled={loading} />
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">Barangay</label>
            <input className="form-input" placeholder="BARANGAY" value={form.barangay} onChange={set("barangay")} disabled={loading} />
          </div>

          <div className="form-group">
            <label className="form-label">Create Password</label>
            <input className="form-input" type="password" placeholder="CREATE PASSWORD" value={form.password} onChange={set("password")} autoComplete="new-password" disabled={loading} />
          </div>

          {error && <div className="error-box">{error}</div>}

          <button className="btn-primary" type="submit" disabled={loading}>
            {loading ? "Creating account…" : "SIGN UP"}
          </button>
        </form>

        <div className="auth-footer-link">
          Already have an account?{" "}
          <button onClick={() => onNavigate("login")}>Log In</button>
        </div>
      </div>
    </div>
  );
}
